
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_m08_hx_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_m08_hx", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([3.725255639852631e-03, -3.838755852758459e-02, -9.202820402751807e-02, -1.537329075603357e-01, -2.093558039833705e-01, -2.259872786467882e-01, -1.621114719507917e-01, -4.591642654684048e-02, 1.255465574932337e-02, 6.475402889041135e-02, 3.149322464544137e-03, -7.186540311182768e-02, -4.182182985265346e-02, -2.376856390013094e-02, 1.266415007604959e-02, -4.183101083932878e-03, -8.106023228452049e-02, -5.544203031848462e-02, -1.595059074914591e-02, -2.274341889271067e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


